import{z as i,x as l,o as A,c as d,q as B,j as n,D as a,d as t,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"复盘与案例写作","description":"","frontmatter":{"title":"复盘与案例写作","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/research-postmortem.md","filePath":"quant/research-postmortem.md","lastUpdated":1791413859000}'),p={name:"quant/research-postmortem.md"};function m(D,E,h,C,c,u){const r=l("Mermaid");return A(),d("div",null,[E[2]||(E[2]=B('<h1 id="复盘与案例写作" tabindex="-1">复盘与案例写作 <a class="header-anchor" href="#复盘与案例写作" aria-label="Permalink to &quot;复盘与案例写作&quot;">​</a></h1><div class="epigraph"><p>研究部门的资产不是净值曲线，是写下来的证据链：哪个假设在何时以何种判据生死，下一次搜索从哪里起笔。</p><footer>—— 据 Arnott, Harvey and Markowitz, Journal of Financial Data Science, 2019；López de Prado, Advances in Financial Machine Learning, 2018 整理</footer></div><p><a href="/quant/live-monitoring-handoff">上一课</a>的触发器把停机的策略自动送回研究账户，附带版本号与对账数据；本课处理闭环的最后一环：无论停机还是继续，一次研究结束都要沉淀成可复用资产——假设台账、失败清单、代码与数据快照。量化主干的课序到此结束：从问题的起源、数据的审计、信号的检验，到组合、成本、风险、上线、监控，最后落回这份复盘；后面没有下一课，只有带着这条链再走一遍的下一次研究。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不复盘有三种代价。其一，同一个坑再挖一次：没有失败清单，搜索会反复撞同一种死法，而且每次碰撞都在暗处消耗一次试验——\\(N\\) 被系统性低估，多重检验折价随之失效，第一单元的纪律在统计上作废。其二，成功归因错误：赚钱不等于假设为真，把因子暴露、运气或执行红利记成 alpha，下一次扩规模时连本带利还回去。其三，组织记忆断裂：过程停在个人脑子里，人一走，同一问题从零重开，连「为什么当初没走这条路」都无人能答。三者共同指向一个事实：研究的产出不是那笔策略，是证据链本身。</p><p><span class="marginnote">「赚钱不等于假设为真」值得展开：策略可能因为恰好超配了某个行业（因子暴露）、赶上顺风行情（运气）或成交比假设便宜（执行红利）而赚钱，与原假设毫无关系。初学者容易把盈亏当裁判——盈亏只是一次抽样，只有事先写明判据的检验才有资格当裁判。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>沉淀物固定四件，缺一不收。<strong>假设台账</strong>：预注册的主假设、次要假设、判据与终止规则，加上实际发生的时间线——何时晋级、何时回滚、何时停机，直接取自监控日志与晋级版本，不靠回忆补写。<strong>失败清单</strong>：每个被拒假设一行，写问题、判据、拒绝原因。失败研究与成功同一模板：写清「当时为何合理」与「哪条判据杀死了它」，禁止以一句「效果不好」归档——没有死因的失败不是数据，是情绪。</p><p><span class="marginnote">「数据 vintage」指数据集的版本快照：同一个宏观指标，初值公布、次月修正、一年后再修正，数值可能各不相同。复现时只锁代码、不锁 vintage，两次运行读到的可能根本不是同一份数据——「跑不出当初的结果」多半不是代码的锅，是数据在暗地里变了。</span><strong>快照</strong>：代码哈希、数据 vintage、配置发布，与<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>的版本发布物是同一件事的收尾一半：能复现，才谈得上复盘。<strong>案例</strong>：一页纸——机制假设、结果、迁移条件：这条教训在什么前提下适用于下一个问题。</p><p><span class="marginnote">迁移条件是案例与吐槽的区别：「这个信号死于参与率」是吐槽；「凡持仓集中于 ADV 后 20% 名字的信号，容量检验先于显著性检验」是案例——后者能被检索，也能被反驳。</span></p>',10)),(A(),n(s,null,{default:a(()=>[o(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20END%5B%22%E7%A0%94%E7%A9%B6%E7%BB%93%E6%9D%9F%EF%BC%9A%E5%81%9C%E6%9C%BA%E6%88%96%E7%BB%A7%E7%BB%AD%22%5D%20--%3E%20LED%5B%22%E5%81%87%E8%AE%BE%E5%8F%B0%E8%B4%A6%EF%BC%9A%E9%A2%84%E6%B3%A8%E5%86%8C%2B%E6%97%B6%E9%97%B4%E7%BA%BF%22%5D%0A%20%20END%20--%3E%20FAIL%5B%22%E5%A4%B1%E8%B4%A5%E6%B8%85%E5%8D%95%EF%BC%9A%E5%88%A4%E6%8D%AE%2B%E6%AD%BB%E5%9B%A0%22%5D%0A%20%20END%20--%3E%20SNAP%5B%22%E5%BF%AB%E7%85%A7%EF%BC%9A%E4%BB%A3%E7%A0%81%E5%93%88%E5%B8%8C%2B%E6%95%B0%E6%8D%AE%20vintage%22%5D%0A%20%20LED%20--%3E%20CASE%5B%22%E4%B8%80%E9%A1%B5%E6%A1%88%E4%BE%8B%EF%BC%9A%E6%9C%BA%E5%88%B6%2B%E8%BF%81%E7%A7%BB%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20FAIL%20--%3E%20CASE%0A%20%20SNAP%20--%3E%20CASE%0A%20%20CASE%20--%3E%20LIB%5B%22%E6%A1%88%E4%BE%8B%E5%BA%93%EF%BC%9A%E6%88%90%E5%8A%9F%E4%B8%8E%E5%A4%B1%E8%B4%A5%E5%90%8C%E6%9D%83%22%5D%0A%20%20LIB%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E6%AC%A1%E7%A0%94%E7%A9%B6%E7%9A%84%E8%B5%B7%E7%AC%94%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"复盘的统计机制是 \\(N\\) 的完整性：被拒假设进台账，试验总数才是真数，折价与过拟合概率才可计算。纪律至此完成闭环——预注册把自由度锁在事前，监控把实盘改动锁成新试验，复盘把所有试验锁进同一本账；任何一环缺位，其余环节的统计承诺都兑现不了。经济机制是搜索的复利：失败清单把隐性搜索轨迹变成显性资产，新问题起笔于旧证据；案例写作让跨策略的模式显形——容量、拥挤、成本低估这类死法在不同信号里反复出现，见过三次的人不再需要第四次。",-1)),E[5]||(E[5]=e("p",null,"三个环节锁的是同一本账：",-1)),(A(),n(s,null,{default:a(()=>[o(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20PRE%5B%22%E9%A2%84%E6%B3%A8%E5%86%8C%EF%BC%9A%E9%80%89%E6%8B%A9%E9%94%81%E5%9C%A8%E4%BA%8B%E5%89%8D%22%5D%20--%3E%20LED%5B%22%E5%90%8C%E4%B8%80%E6%9C%AC%E8%AF%95%E9%AA%8C%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20MON%5B%22%E7%9B%91%E6%8E%A7%EF%BC%9A%E5%AE%9E%E7%9B%98%E6%94%B9%E5%8A%A8%3D%E6%96%B0%E8%AF%95%E9%AA%8C%22%5D%20--%3E%20LED%0A%20%20POST%5B%22%E5%A4%8D%E7%9B%98%EF%BC%9A%E8%A2%AB%E6%8B%92%E5%81%87%E8%AE%BE%E5%85%A8%E9%83%A8%E5%85%A5%E8%B4%A6%22%5D%20--%3E%20LED%0A%20%20LED%20--%3E%20N%5B%22N%20%3D%20%E7%9C%9F%E5%AE%9E%E8%AF%95%E9%AA%8C%E6%80%BB%E6%95%B0%22%5D%0A%20%20N%20--%3E%20STAT%5B%22%E4%BF%AE%E6%AD%A3%E6%8A%98%E4%BB%B7%E6%89%8D%E5%8F%AF%E8%AE%A1%E7%AE%97%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<p><span class="marginnote">幸存者偏差的经典版本是二战战机装甲：军方统计返航机上的弹孔分布来决定加固位置，却漏了真正致命的部位——因为坠落的飞机没机会进样本。只收成功案例的案例库同理：你检索到的永远是「活下来的做法」，而死因清单才是坠毁那批机带来的信息。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>复盘不是追责：以惩罚收尾的组织只会隐藏试验，\\(N\\) 的低估更严重——免责是数据质量的前提，责任只落在流程违规上。快照不是活代码：依赖漂移让「能跑」逐年腐化，复现要靠容器与数据 vintage 双冻结。案例库只收成功，就重新制造幸存者偏差：负结果必须与成功同权可见、同样可检索。数据许可限制快照的流转范围，案例应引用口径与判据而非搬运数据本身。最后，复盘自身也要有截止：证据链写到停机或当期决策为止，不无限回写——把复盘写成新研究，是另一种形式的样本内。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>研究的沉淀物四件：假设台账、失败清单、可复现快照、带迁移条件的一页案例。</li><li>失败与成功同模板归档，死因必须落在判据上；「效果不好」不是数据。</li><li>\\(N\\) 的完整性靠台账维持，多重检验折价在实盘阶段依然有效。</li><li>复盘免责、案例同权、快照双冻结；负结果可检索才不产生幸存者偏差。</li><li>出处：Arnott, Harvey and Markowitz, <em>JFDS</em>, 2019；López de Prado, <em>AFML</em>, 2018；版本与隔离原则见<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>。</li></ul>',5))])}const g=i(p,[["render",m]]);export{f as __pageData,g as default};
